import React, {useState, useEffect} from 'react';
import { API } from './config';
import dayjs from 'dayjs';

function App(){
  const [view, setView] = useState('home');
  const [adminToken, setAdminToken] = useState('');
  const [userToken, setUserToken] = useState('');
  const [stats, setStats] = useState(null);
  const [challans, setChallans] = useState([]);
  const [form, setForm] = useState({});

  useEffect(()=> {
    // nothing on load
  },[]);

  async function adminLogin(e){
    e.preventDefault();
    const res = await fetch(API + '/admin/login', {
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({ username: form.username, password: form.password })
    });
    const data = await res.json();
    if(data.token){ setAdminToken(data.token); alert('Admin logged in'); setView('admin'); fetchAll(); }
    else alert(data.message || 'Error');
  }

  async function fetchAll(){
    const res = await fetch(API + '/challan/all');
    const data = await res.json();
    setStats({total:data.total, paid:data.paid, pending:data.pending});
    setChallans(data.challans);
  }

  async function addChallan(e){
    e.preventDefault();
    const payload = {
      userId: form.userId || null,
      vehicleNumber: form.vehicleNumber,
      cause: form.cause,
      fine: Number(form.fine),
      address: form.address,
      issueDate: dayjs().format('YYYY-MM-DD'),
      dueDate: form.dueDate || dayjs().add(7,'day').format('YYYY-MM-DD')
    };
    const res = await fetch(API + '/challan/add', {
      method:'POST',
      headers:{'Content-Type':'application/json', 'Authorization': adminToken},
      body: JSON.stringify(payload)
    });
    const data = await res.json();
    if(data.challan){ alert('Challan added'); fetchAll(); } else alert(data.message || 'Error');
  }

  // Minimal UI
  return (
    <div style={{padding:20,fontFamily:'sans-serif'}}>
      <h1>Traffic Challan System (Demo)</h1>
      <div style={{marginBottom:20}}>
        <button onClick={()=>setView('home')}>Home</button>
        <button onClick={()=>setView('adminLogin')}>Admin Login</button>
        <button onClick={()=>setView('admin')}>Admin Panel</button>
        <button onClick={()=>setView('user')}>User Panel</button>
      </div>

      {view==='home' && <div>
        <p>Use the buttons to navigate. Backend must be running at the API URL in src/config.js</p>
      </div>}

      {view==='adminLogin' && <form onSubmit={adminLogin}>
        <h3>Admin Login</h3>
        <input placeholder='username' onChange={e=>setForm({...form,username:e.target.value})} /><br/>
        <input type='password' placeholder='password' onChange={e=>setForm({...form,password:e.target.value})} /><br/>
        <button type='submit'>Login</button>
      </form>}

      {view==='admin' && <>
        <h3>Admin Panel</h3>
        <div>
          <strong>Stats:</strong> {stats ? `Total: ${stats.total} | Paid: ${stats.paid} | Pending: ${stats.pending}` : 'No data'}
          <button onClick={fetchAll} style={{marginLeft:10}}>Refresh</button>
        </div>

        <h4>Add Challan</h4>
        <form onSubmit={addChallan}>
          <input placeholder='userId (optional)' onChange={e=>setForm({...form,userId:e.target.value})} /><br/>
          <input placeholder='vehicleNumber' onChange={e=>setForm({...form,vehicleNumber:e.target.value})} /><br/>
          <input placeholder='cause' onChange={e=>setForm({...form,cause:e.target.value})} /><br/>
          <input placeholder='fine' onChange={e=>setForm({...form,fine:e.target.value})} /><br/>
          <input placeholder='address' onChange={e=>setForm({...form,address:e.target.value})} /><br/>
          <input placeholder='dueDate (YYYY-MM-DD)' onChange={e=>setForm({...form,dueDate:e.target.value})} /><br/>
          <button type='submit'>Add Challan</button>
        </form>

        <h4>All Challans</h4>
        <table border='1' cellPadding='6'>
          <thead><tr><th>#</th><th>Vehicle</th><th>Cause</th><th>Fine</th><th>Status</th><th>Issue</th></tr></thead>
          <tbody>
            {challans.map((c,i)=>(<tr key={c._id}><td>{i+1}</td><td>{c.vehicleNumber}</td><td>{c.cause}</td><td>{c.fine}</td><td>{c.status}</td><td>{c.issueDate}</td></tr>))}
          </tbody>
        </table>
      </>}

      {view==='user' && <UserPanel setUserToken={setUserToken} userToken={userToken} />}

    </div>
  )
}

export default App;

function UserPanel({setUserToken,userToken}){
  const [form,setForm] = React.useState({});
  const [myChallans,setMyChallans] = React.useState([]);
  async function signup(e){
    e.preventDefault();
    const res = await fetch(API + '/user/signup', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(form)});
    const data = await res.json();
    alert(data.message || 'ok');
  }
  async function login(e){
    e.preventDefault();
    const res = await fetch(API + '/user/login', { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({ email: form.email, password: form.password })});
    const data = await res.json();
    if(data.token){ setUserToken(data.token); localStorage.setItem('uid', data.userId); alert('Logged in'); fetchMine(data.userId); }
    else alert(data.message || 'Error');
  }
  async function fetchMine(userId){
    const id = userId || localStorage.getItem('uid');
    if(!id) return alert('No user id');
    const res = await fetch(API + '/challan/user/' + id);
    const data = await res.json();
    setMyChallans(data);
  }
  async function pay(challanId){
    const res = await fetch(API + '/challan/pay/' + challanId, { method:'POST' });
    const data = await res.json();
    alert(data.message || 'Paid');
    fetchMine();
  }
  return (
    <div>
      <h3>User</h3>
      <div style={{display:'flex',gap:20}}>
        <form onSubmit={signup}><h4>Signup</h4>
          <input placeholder='name' onChange={e=>setForm({...form,name:e.target.value})} /><br/>
          <input placeholder='email' onChange={e=>setForm({...form,email:e.target.value})} /><br/>
          <input placeholder='vehicleNumber' onChange={e=>setForm({...form,vehicleNumber:e.target.value})} /><br/>
          <input type='password' placeholder='password' onChange={e=>setForm({...form,password:e.target.value})} /><br/>
          <button>Signup</button>
        </form>

        <form onSubmit={login}><h4>Login</h4>
          <input placeholder='email' onChange={e=>setForm({...form,email:e.target.value})} /><br/>
          <input type='password' placeholder='password' onChange={e=>setForm({...form,password:e.target.value})} /><br/>
          <button>Login</button>
        </form>
      </div>

      <div>
        <h4>My Challans</h4>
        <button onClick={()=>fetchMine()}>Refresh</button>
        <table border='1' cellPadding='6'>
          <thead><tr><th>#</th><th>Vehicle</th><th>Cause</th><th>Fine</th><th>Status</th><th>Action</th></tr></thead>
          <tbody>
            {myChallans.map((c,i)=>(<tr key={c._id}><td>{i+1}</td><td>{c.vehicleNumber}</td><td>{c.cause}</td><td>{c.fine}</td><td>{c.status}</td><td>{c.status!=='Paid' && <button onClick={()=>pay(c._id)}>Pay</button>}</td></tr>))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
